    25	    public void createReservation(Context ctx) throws SQLException {
    26	        CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
    27	
    28	        validateRequest(request);
    29	
    30	        RatePlan ratePlan = RatePlan.valueOf(request.getRatePlan());
    31	
