    39	            request.getGuests(),
    40	            ratePlan
    41	        );
    42	
    43	        Room room = roomService.getRoomByNumber(reservation.getRoomNumber());
    44	        ctx.status(201).json(new ReservationResponse(reservation, room));
    45	    }
