     1	package com.pousadamarealta.domain.event;
     2	
     3	import java.util.ArrayList;
     4	import java.util.List;
     5	
     6	public class EventPublisher {
     7	    private final List<ReservationConfirmedListener> confirmedListeners = new ArrayList<>();
     8	    private final List<ReservationCancelledListener> cancelledListeners = new ArrayList<>();
     9	
    10	    public void registerConfirmedListener(ReservationConfirmedListener listener) {
    11	        confirmedListeners.add(listener);
    12	    }
    13	
    14	    public void registerCancelledListener(ReservationCancelledListener listener) {
    15	        cancelledListeners.add(listener);
    16	    }
    17	
    18	    public void publishConfirmed(ReservationConfirmedEvent event) {
    19	        for (ReservationConfirmedListener listener : confirmedListeners) {
    20	            listener.onReservationConfirmed(event);
    21	        }
    22	    }
    23	
    24	    public void publishCancelled(ReservationCancelledEvent event) {
    25	        for (ReservationCancelledListener listener : cancelledListeners) {
    26	            listener.onReservationCancelled(event);
    27	        }
    28	    }
    29	
    30	    public interface ReservationConfirmedListener {
    31	        void onReservationConfirmed(ReservationConfirmedEvent event);
    32	    }
