    10	import java.math.BigDecimal;
    11	import java.text.NumberFormat;
    12	import java.util.Locale;
    13	
    14	public class FinanceNotificationListener implements
    15	        EventPublisher.ReservationConfirmedListener,
    16	        EventPublisher.ReservationCancelledListener {
    17	
    18	    private static final String FINANCE_EMAIL = "financeiro@pousadamarealta.com.br";
    19	    private static final Locale LOCALE_BR = new Locale.Builder().setLanguage("pt").setRegion("BR").build();
    20	
    21	    private final MessageService messageService;
    22	
    23	    public FinanceNotificationListener(MessageService messageService) {
    24	        this.messageService = messageService;
    25	    }
    26	
    27	    @Override
    28	    public void onReservationConfirmed(ReservationConfirmedEvent event) {
    29	        Reservation reservation = event.getReservation();
    30	
    31	        String subject = String.format("Pagamento recebido - reserva %d", reservation.getId());
    32	        String body = String.format(
    33	            "Valor: %s",
    34	            formatMoney(reservation.getAmountPaid())
    35	        );
    36	
    37	        Message message = new Message("EMAIL", FINANCE_EMAIL, subject, body);
    38	        messageService.send(message);
    39	    }
    40	
    41	    @Override
    42	    public void onReservationCancelled(ReservationCancelledEvent event) {
    43	        if (!event.wasConfirmed()) {
    44	            return;
    45	        }
    46	
    47	        Reservation reservation = event.getReservation();
    48	
    49	        if (reservation.getRefund() == null || reservation.getRefund().compareTo(BigDecimal.ZERO) == 0) {
    50	            return;
    51	        }
    52	
    53	        String subject = String.format("Reembolso - reserva %d", reservation.getId());
    54	        String body = String.format(
    55	            "Valor: %s",
    56	            formatMoney(reservation.getRefund())
    57	        );
    58	
    59	        Message message = new Message("EMAIL", FINANCE_EMAIL, subject, body);
    60	        messageService.send(message);
    61	    }
    62	
    63	    private String formatMoney(BigDecimal amount) {
    64	        NumberFormat currencyFormatter = NumberFormat.getCurrencyInstance(LOCALE_BR);
    65	        return currencyFormatter.format(amount);
    66	    }
    67	}
